const formCodes=[
{code:'1001-66',vak:'II',label:'Je burgerlijke staat op 1 januari 2026',plain:'Kruis dit aan als je op die datum ongehuwd was en niet wettelijk samenwoonde. Het gaat om je toestand op die specifieke dag.',page:10},
{code:'1002-65',vak:'II',label:'Gehuwd of wettelijk samenwonend',plain:'Deze code gaat over je burgerlijke staat op 1 januari 2026. Bij een feitelijke scheiding kunnen extra vragen en codes gelden.',page:10},
{code:'1030-37',vak:'II',label:'Kinderen die volledig fiscaal ten laste zijn',plain:'Vul hier het aantal kinderen in dat volgens de fiscale regels volledig te jouw laste is. Thuis wonen of studeren is op zichzelf niet genoeg om dat te bepalen.',page:16},
{code:'1105-59',vak:'III',label:'Vastgoed dat je voor je beroep gebruikt',plain:'Deze rubriek gaat over onroerende goederen die je beroepsmatig gebruikt. De voorbereiding vraagt het bedrag van het kadastraal inkomen.',page:21},
{code:'1106-58',vak:'III',label:'Bepaalde gebouwen die je niet verhuurt of privé verhuurt',plain:'Dit is een rubriek voor gebouwen in de situaties die letterlijk naast de code staan, zoals niet verhuren of privéverhuur aan een particulier die het niet beroepsmatig gebruikt.',page:23},
{code:'1250-11',vak:'IV',label:'Lonen en wedden volgens fiche 281.10',plain:'Dit is de gewone code voor loonbedragen die op je fiche 281.10 staan. Neem het bedrag van je fiche over en controleer de vooraf ingevulde informatie.',page:27},
{code:'250',vak:'IV',label:'Loonbedrag op fiche 281.10',plain:'De fiche 281.10 vermeldt loonbedragen naast code 250. In de voorbereiding staan gewone loonbedragen onder meer bij rubriek A, 1.',page:27},
{code:'1286-72',vak:'IV',label:'Totaal van de bedrijfsvoorheffing',plain:'Bedrijfsvoorheffing is belasting die al werd ingehouden. Deze code telt de voorheffing volgens je fiches en de genoemde rubriek samen.',page:43},
{code:'286',vak:'IV',label:'Bedrijfsvoorheffing op je fiche',plain:'Op je loonfiche vind je de ingehouden bedrijfsvoorheffing naast code 286. Dit is al ingehouden belasting, niet automatisch het definitieve bedrag dat je verschuldigd bent.',page:43},
{code:'1228-33',vak:'V',label:'Gewoon wettelijk pensioen',plain:'Deze code hoort bij gewone wettelijke pensioenbedragen die je kreeg vanaf de wettelijke pensioenleeftijd. Je pensioenfiche vermeldt de bedragen.',page:46},
{code:'1192-69',vak:'VI',label:'Gewone ontvangen onderhoudsuitkeringen',plain:'Dit is het werkelijk ontvangen bedrag van niet-gekapitaliseerde onderhoudsuitkeringen. De toelichting legt uit welke betalingen als onderhoudsuitkering tellen en hoe ze worden behandeld.',page:52},
{code:'1390-65',vak:'VIII',label:'Onderhoudsuitkeringen die jij zelf betaalde',plain:'Vul het werkelijk betaalde bedrag alleen in als de betaling aan de fiscale voorwaarden voldoet. Bewaar de bewijsstukken en lees de toelichting over welke uitkeringen meetellen.',page:63},
{code:'1151-13',vak:'VII',label:'Bepaalde interest op gereglementeerde spaarrekeningen',plain:'Deze code gaat over interest op gereglementeerde spaarrekeningen binnen de beschreven voorwaarden, wanneer geen roerende voorheffing werd ingehouden. De officiële toelichting legt uit welke grens en berekening gelden.',page:54},
{code:'1394-61',vak:'X',label:'Giften',plain:'Deze code is voor giften die volgens de regels in aanmerking komen voor een belastingvermindering. Een betaling is niet automatisch een geldige gift voor deze rubriek.',page:90},
{code:'1384-71',vak:'X',label:'Uitgaven voor kinderoppas',plain:'Hier gaat het om het bedrag van kinderopvangkosten dat voor een belastingvermindering in aanmerking komt. Niet elke opvangkost telt mee; de voorwaarden en attesten zijn belangrijk.',page:90},
{code:'1361-94',vak:'X',label:'Betalingen voor pensioensparen',plain:'Deze rubriek vermeldt betalingen voor pensioensparen. Kijk naar het attest van je financiële instelling en naar de voorwaarden voor het juiste jaar.',page:90},
{code:'3334-61',vak:'IX',label:'Bepaalde oudere hypothecaire leningen: interesten en aflossingen',plain:'Deze code hoort bij interesten en kapitaalaflossingen van hypothecaire leningen uit 2016 tot 2019 die aan de voorwaarden voor de geïntegreerde woonbonus voldoen. Alleen een lening hebben is niet genoeg om dit bedrag hier in te vullen.',page:65},
{code:'3377-18',vak:'XI',label:'Openstaand saldo Winwinlening op 1 januari 2025',plain:'Dit is het nog openstaande bedrag van de Winwinlening op de vermelde datum. Gebruik de gegevens van de lening en controleer of ze onder de Vlaamse regeling valt.',page:102},
{code:'1570-79',vak:'XII',label:'Totaal van je voorafbetalingen',plain:'Tel de voorafbetalingen voor aanslagjaar 2026 op volgens de officiële gegevens. Voorafbetalingen zijn voorschotten die later met de berekende belasting worden verrekend.',page:104},
{code:'1075-89',vak:'XIII',label:'Melding van een buitenlandse rekening',plain:'Deze ja/nee-vraag vraagt of jij, je partner bij een gezamenlijke aangifte of een minderjarig kind in 2025 een rekening bij een buitenlandse financiële instelling had of beheerde. Een melding betekent niet op zichzelf dat het saldo belastbaar inkomen is.',page:105}
];

const $=(s,r=document)=>r.querySelector(s);const $$=(s,r=document)=>[...r.querySelectorAll(s)];
function renderSteps(){$('#routeGrid').innerHTML=routeSteps.map(([n,t,d,i,c],idx)=>`<article class="route-step"><div class="step-top"><span class="step-number ${c}">${n}</span>${idx<5?'<span class="step-connector">→</span>':''}</div><span class="step-icon ${c}">${({inkomsten:'↗',voorheffing:'−',aangifte:'▤',berekening:'∑',verrekening:'↔',saldo:'€'})[i]}</span><h3>${t}</h3><p>${d}</p></article>`).join('')}
function normalize(value){return value.toLocaleLowerCase('nl-BE').normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim()}
function renderFormGuide(query='') {const q=normalize(query);const partOne=topics.filter(t=>t.part===1);const matchedCodes=formCodes.filter(c=>!q||normalize(`${c.code} ${c.label} ${c.plain} vak ${c.vak}`).includes(q));const matchedTopics=partOne.filter(t=>!q||normalize(`vak ${t.id} ${t.title} ${t.one} ${t.search}`).includes(q));$('#formCodeResults').innerHTML=q?(matchedCodes.length?matchedCodes.map(c=>`<button type="button" class="form-code-result" data-form-code="${c.code}"><code>Code ${c.code} · Vak ${c.vak}</code><span>${c.label}</span><small>${c.plain}</small></button>`).join(''):'<p class="empty-state">Geen code uit de snelle lijst gevonden. Kies hieronder een vak of probeer een andere zoekterm.</p>'):'';$$('[data-form-code]').forEach(b=>b.addEventListener('click',()=>openFormCode(b.dataset.formCode)));$('#formVakGrid').innerHTML=matchedTopics.map(t=>`<button type="button" class="form-vak-button" data-form-vak="${t.id}"><span>VAK ${t.id}<b>${t.title}</b></span><i aria-hidden="true">→</i></button>`).join('')||'<p class="empty-state">Geen vak gevonden. Wis de zoekopdracht om alle vakken te zien.</p>';$$('[data-form-vak]').forEach(b=>b.addEventListener('click',()=>openTopic(b.dataset.formVak)))}
function openFormCode(code){const c=formCodes.find(x=>x.code===code);if(!c)return;const topic=topics.find(x=>x.id===c.vak);$('#dialogBody').innerHTML=`<span class="dialog-kicker">AANGIFTE 2026 · VAK ${c.vak}</span><h2 id="detailTitle">Code ${c.code}</h2><p class="dialog-intro">${c.label}</p><div class="form-code-dialog-note"><b>In gewone taal</b><br>${c.plain}</div><div class="dialog-section"><h3>Wat vul je in?</h3><p>Deze voorbereiding is een leeg overzicht. Gebruik de bedragen op je officiële fiches of attesten en controleer wat al vooraf is ingevuld. De juiste code hangt af van de vraag en jouw situatie.</p></div><div class="dialog-section"><h3>Voor wie is dit?</h3><p>${topic?topic.who:'Voor wie deze rubriek van toepassing is.'}</p></div><div class="dialog-source"><b>Officiële toelichting</b><span>Deel 1, Vak ${c.vak}, pagina ${c.page}. De officiële tekst is bepalend.</span><a target="_blank" rel="noreferrer" href="${urls.part1}#page=${c.page}">Open deze uitleg ↗</a></div><div class="dialog-terms"><b>Bekijk het hele vak</b><button type="button" data-code-topic="${c.vak}">Vak ${c.vak} · ${topic?.title||''} →</button></div>`;$$('[data-code-topic]',$('#dialogBody')).forEach(b=>b.addEventListener('click',()=>openTopic(b.dataset.codeTopic)));if(!$('#detailDialog').open)$('#detailDialog').showModal()}
function card(topic){return `<button class="topic-card" data-id="${topic.id}" type="button"><div class="topic-top"><span class="topic-icon" aria-hidden="true">${topic.icon}</span><span class="topic-tag">${topic.tag}</span><span class="topic-arrow" aria-hidden="true">↗</span></div><span class="topic-code">VAK ${topic.id}</span><b>${topic.title}</b><small>${topic.short}</small></button>`}
function renderCatalog(part='all',query=''){const q=normalize(query);const filtered=topics.filter(t=>(part==='all'||String(t.part)===part)&&normalize(Object.values(t).join(' ')).includes(q));const matchingTerms=q?terms.filter(t=>normalize(Object.values(t).join(' ')).includes(q)).slice(0,6):[];const parts=part==='all'?['1','2']:[part];const rowsMarkup=parts.map(p=>{const rows=filtered.filter(t=>String(t.part)===p);return rows.length?`<section class="catalog-part" aria-label="Deel ${p}"><div class="part-heading"><span>DEEL ${p}</span><i></i><small>${p==='1'?'Voor alle belastingplichtigen':'Voor bepaalde beroeps- en inkomenssituaties'}</small></div><div class="topic-grid">${rows.map(card).join('')}</div></section>`:''}).join('');const termsMarkup=matchingTerms.length?`<section class="term-results" aria-label="Begrippen"><h3>Begrippen die passen bij je zoekopdracht</h3><div>${matchingTerms.map(t=>`<button type="button" data-term="${t.id}">${t.name}<span aria-hidden="true">↗</span></button>`).join('')}</div></section>`:'';$('#catalogGrid').innerHTML=`${termsMarkup}${rowsMarkup}`||'<div class="empty-state">Geen vak of begrip gevonden. Probeer een andere zoekterm.</div>';$('#searchSummary').textContent=q?`${filtered.length} ${filtered.length===1?'vak':'vakken'} en ${matchingTerms.length} ${matchingTerms.length===1?'begrip':'begrippen'} gevonden.`:'';$$('.topic-card').forEach(b=>b.addEventListener('click',()=>openTopic(b.dataset.id)));$$('.term-results [data-term]').forEach(b=>b.addEventListener('click',()=>{openTerm(b.dataset.term);if(!$('#detailDialog').open)$('#detailDialog').showModal()}))}
function openTopic(id){const t=topics.find(x=>x.id===id);if(!t)return;$('#dialogBody').innerHTML=`<span class="dialog-kicker">DEEL ${t.part} · VAK ${t.id}</span><h2 id="detailTitle">${t.title}</h2><p class="dialog-intro">${t.one}</p><div class="dialog-section"><h3>Wat vind je hier terug?</h3><p>${t.found}</p></div><div class="dialog-section"><h3>Voor wie is dit vak belangrijk?</h3><p>${t.who}</p></div><div class="dialog-example"><span>CONCREET VOORBEELD</span><p>${t.example}</p></div><div class="dialog-section"><h3>Hoe werkt dit fiscaal?</h3><p>${t.tax}</p></div><div class="dialog-section"><h3>Veelgemaakte fout</h3><p>${t.mistake}</p></div><div class="dialog-source"><b>Officiële informatie</b><span>${t.source}</span><a target="_blank" rel="noreferrer" href="${t.part===1?urls.part1:urls.part2}">Open de officiële toelichting ↗</a></div><div class="dialog-terms"><b>Ga dieper</b>${t.terms.map(id=>{let x=terms.find(z=>z.id===id);return x?`<button type="button" data-term="${id}">${x.name} →</button>`:''}).join('')}</div>`;$$('[data-term]',$('#dialogBody')).forEach(b=>b.addEventListener('click',()=>openTerm(b.dataset.term)));if(!$('#detailDialog').open)$('#detailDialog').showModal()}
function openTerm(id){const t=terms.find(x=>x.id===id);if(!t)return;$('#dialogBody').innerHTML=`<span class="dialog-kicker">BEGRIP IN MENSENTAAL</span><h2 id="detailTitle">${t.name}</h2><p class="dialog-intro">${t.meaning}</p><div class="dialog-section"><h3>Waarom is het belangrijk?</h3><p>${t.importance}</p></div><div class="dialog-section"><h3>Waar komt het voor?</h3><p>${t.where}</p></div><div class="dialog-example"><span>CONCREET VOORBEELD</span><p>${t.example}</p></div><div class="dialog-section"><h3>Vaak verkeerd begrepen</h3><p>${t.misread}</p></div><div class="dialog-terms"><b>Bekijk verwante vakken</b>${topics.filter(x=>x.terms.includes(id)).slice(0,4).map(x=>`<button type="button" data-topic="${x.id}">Vak ${x.id} · ${x.title} →</button>`).join('')}</div>`;$$('[data-topic]',$('#dialogBody')).forEach(b=>b.addEventListener('click',()=>openTopic(b.dataset.topic)))}
function renderTerms(){$('#termGrid').innerHTML=terms.map(t=>`<button class="term-card" data-term="${t.id}" type="button"><span>${t.icon}</span><b>${t.name}</b><i>↗</i></button>`).join('');$$('.term-card').forEach(b=>b.addEventListener('click',()=>{openTerm(b.dataset.term);$('#detailDialog').showModal()}))}
let quizIndex=0,answers={};function drawQuiz(){const q=quizQuestions[quizIndex];$('#stepLabel').textContent=String(Math.min(quizIndex+1,quizQuestions.length)).padStart(2,'0');$('#quizBack').hidden=quizIndex===0;$('#quizNext').textContent=quizIndex===quizQuestions.length-1?'Bekijk mijn route →':'Verder →';if(quizIndex===quizQuestions.length){const ids=[...new Set(Object.entries(answers).filter(([,v])=>v==='Ja').flatMap(([k])=>quizMap[k]))];$('#quizContent').innerHTML=`<div class="quiz-kicker">JOUW MOGELIJKE ROUTE</div><h3>Dit zijn goede plekken om te beginnen.</h3><p class="quiz-explain">Je keuzes kunnen wijzen op deze onderdelen. Ook andere vakken kunnen van toepassing zijn: dit is geen officiële beslissing.</p><div class="quiz-results">${ids.length?ids.map(id=>{const t=topics.find(x=>x.id===id);return `<button type="button" data-result="${id}"><span>Vak ${id}</span><b>${t.title}</b><small>${t.who}</small><i aria-hidden="true">↗</i></button>`}).join(''):'<p>Kies “Ja” bij wat van toepassing is om mogelijke vakken te zien. Je kunt je antwoorden steeds aanpassen.</p>'}</div><button class="restart-quiz" id="restartQuiz" type="button">Antwoorden wijzigen ↻</button>`;$$('[data-result]').forEach(b=>b.onclick=()=>openTopic(b.dataset.result));$('#restartQuiz').onclick=()=>{quizIndex=0;answers={};drawQuiz()};return}$('#quizContent').innerHTML=`<div class="quiz-kicker">VRAAG ${String(quizIndex+1).padStart(2,'0')} VAN 06</div><h3>${q.q}</h3><p class="quiz-explain">Geen antwoord is fout. Kies “weet ik niet” als je twijfelt.</p><div class="quiz-options">${q.options.map(o=>`<button class="quiz-option ${answers[q.key]===o?'selected':''}" data-answer="${o}" type="button" aria-pressed="${answers[q.key]===o}"><span class="radio" aria-hidden="true"></span>${o}<i aria-hidden="true">↗</i></button>`).join('')}</div>`;$$('[data-answer]').forEach(b=>b.onclick=()=>{answers[q.key]=b.dataset.answer;drawQuiz()})}
function renderFaq(){ $('#faqList').innerHTML=faqs.map(([q,a],i)=>`<details class="faq-item" ${i===0?'':''}><summary>${q}<span>+</span></summary><p>${a}</p></details>`).join('')}
function renderSources(){$('#sourceList').innerHTML=sources.map(([n,u,d])=>`<a class="source-row" href="${u}" target="_blank" rel="noreferrer"><span class="source-number">↗</span><span><b>${n}</b><small>${d}</small></span><i>↗</i></a>`).join('')}
function calc(){const due=Math.max(0,Number($('#taxDue').value)||0),paid=Math.max(0,Number($('#taxPaid').value)||0),delta=Math.abs(paid-due);if(paid>=due){$('#calcCaption').textContent='JE KRIJGT MOGELIJK TERUG';$('#calcEquation').textContent=`${fmt(paid)} betaald − ${fmt(due)} belasting`;$('#calcResult')?.classList.remove('owe');$('.calc-result').classList.remove('owe')}else{$('#calcCaption').textContent='JE BETAALT MOGELIJK BIJ';$('#calcEquation').textContent=`${fmt(due)} belasting − ${fmt(paid)} betaald`;$('.calc-result').classList.add('owe')}$('#calcAmount').textContent=fmt(delta)}function fmt(n){return new Intl.NumberFormat('nl-BE',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(n)}
renderSteps();renderCatalog();renderFormGuide();renderTerms();renderFaq();renderSources();drawQuiz();calc();
$('#formCodeSearch').addEventListener('input',()=>renderFormGuide($('#formCodeSearch').value));
$$('[data-part]').forEach(b=>b.addEventListener('click',()=>{$$('[data-part]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});renderCatalog(b.dataset.part,$('#searchInput').value)}));$('#searchInput').addEventListener('input',()=>renderCatalog($('.segmented .active').dataset.part,$('#searchInput').value));$('#taxDue').addEventListener('input',calc);$('#taxPaid').addEventListener('input',calc);$('#quizNext').addEventListener('click',()=>{if(quizIndex<quizQuestions.length){if(!answers[quizQuestions[quizIndex].key]){const t=$('#toast');t.textContent='Kies een antwoord om verder te gaan.';t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200);return}quizIndex++;drawQuiz()}});$('#quizBack').addEventListener('click',()=>{quizIndex=Math.max(0,quizIndex-1);drawQuiz()});$('.dialog-close').addEventListener('click',()=>$('#detailDialog').close());$('#detailDialog').addEventListener('click',e=>{if(e.target===e.currentTarget)e.currentTarget.close()});$('#menuToggle').addEventListener('click',()=>{const open=$('#menuToggle').getAttribute('aria-expanded')==='true';$('#menuToggle').setAttribute('aria-expanded',String(!open));$('#menuToggle .sr-only').textContent=open?'Menu openen':'Menu sluiten';$('#siteNav').classList.toggle('open',!open)});$$('#siteNav a').forEach(a=>a.addEventListener('click',()=>{$('#menuToggle').setAttribute('aria-expanded','false');$('#menuToggle .sr-only').textContent='Menu openen';$('#siteNav').classList.remove('open')}));document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#searchInput').focus();$('#catalogus').scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'})}});
